package com.pdh.cardvault.desktop

import java.util.Properties

/** Build metadata generated by Gradle (see generateVersionResource in build.gradle.kts). */
internal object DesktopAppInfo {
    private const val VERSION_RESOURCE = "/cardvault-version.properties"
    private const val UNKNOWN_VERSION = "dev"

    val version: String by lazy { readVersion() }

    val windowTitle: String
        get() = "CardVault $version"

    val settingsLabel: String
        get() = "CardVault $version  ·  Windows"

    const val editionLabel: String = "Gemini 4 Carbon Edition · 120Hz 极速流光版"

    internal fun readVersion(
        loader: () -> java.io.InputStream? = {
            DesktopAppInfo::class.java.getResourceAsStream(VERSION_RESOURCE)
        },
    ): String = runCatching {
        loader()?.use { stream ->
            Properties().apply { load(stream) }.getProperty("version")
        }
    }.getOrNull()
        ?.trim()
        ?.takeIf(String::isNotEmpty)
        ?: UNKNOWN_VERSION
}
